window.__code__["app-multi-agent-manager-py"] = {"code_id": "app-multi-agent-manager-py", "kind": "src", "title": "multi_agent_manager.py", "source_path": "QwenPaw-main/src/qwenpaw/app/multi_agent_manager.py", "highlight_line": null, "code_html": "<div class=\"code-body\">\n<div class=\"c-line\" data-line=\"1\"><span class=\"c-no\">1</span><span class=\"c-src\"><span class=\"c-com\"># -*- coding: utf-8 -*-</span></span></div>\n<div class=\"c-line\" data-line=\"2\"><span class=\"c-no\">2</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span>&quot;MultiAgentManager: Manages multiple agent workspaces <span class=\"c-kw\">with</span> lazy loading.</span></div>\n<div class=\"c-line\" data-line=\"3\"><span class=\"c-no\">3</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"4\"><span class=\"c-no\">4</span><span class=\"c-src\">Provides centralized management <span class=\"c-kw\">for</span> multiple Workspace objects,</span></div>\n<div class=\"c-line\" data-line=\"5\"><span class=\"c-no\">5</span><span class=\"c-src\">including lazy loading, lifecycle management, <span class=\"c-kw\">and</span> hot reloading.</span></div>\n<div class=\"c-line\" data-line=\"6\"><span class=\"c-no\">6</span><span class=\"c-src\"><span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"7\"><span class=\"c-no\">7</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"8\"><span class=\"c-no\">8</span><span class=\"c-src\"><span class=\"c-kw\">import</span> asyncio</span></div>\n<div class=\"c-line\" data-line=\"9\"><span class=\"c-no\">9</span><span class=\"c-src\"><span class=\"c-kw\">import</span> logging</span></div>\n<div class=\"c-line\" data-line=\"10\"><span class=\"c-no\">10</span><span class=\"c-src\"><span class=\"c-kw\">import</span> time</span></div>\n<div class=\"c-line\" data-line=\"11\"><span class=\"c-no\">11</span><span class=\"c-src\"><span class=\"c-kw\">from</span> typing <span class=\"c-kw\">import</span> Dict, Set</span></div>\n<div class=\"c-line\" data-line=\"12\"><span class=\"c-no\">12</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"13\"><span class=\"c-no\">13</span><span class=\"c-src\"><span class=\"c-kw\">from</span> qwenpaw.exceptions <span class=\"c-kw\">import</span> (</span></div>\n<div class=\"c-line\" data-line=\"14\"><span class=\"c-no\">14</span><span class=\"c-src\">    ConfigurationException,</span></div>\n<div class=\"c-line\" data-line=\"15\"><span class=\"c-no\">15</span><span class=\"c-src\">)</span></div>\n<div class=\"c-line\" data-line=\"16\"><span class=\"c-no\">16</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"17\"><span class=\"c-no\">17</span><span class=\"c-src\"><span class=\"c-kw\">from</span> .workspace <span class=\"c-kw\">import</span> Workspace</span></div>\n<div class=\"c-line\" data-line=\"18\"><span class=\"c-no\">18</span><span class=\"c-src\"><span class=\"c-kw\">from</span> ..config.utils <span class=\"c-kw\">import</span> load_config</span></div>\n<div class=\"c-line\" data-line=\"19\"><span class=\"c-no\">19</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"20\"><span class=\"c-no\">20</span><span class=\"c-src\">logger = logging.getLogger(__name__)</span></div>\n<div class=\"c-line\" data-line=\"21\"><span class=\"c-no\">21</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"22\"><span class=\"c-no\">22</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"23\"><span class=\"c-no\">23</span><span class=\"c-src\"><span class=\"c-kw\">class</span> MultiAgentManager:</span></div>\n<div class=\"c-line\" data-line=\"24\"><span class=\"c-no\">24</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;Manages multiple agent workspaces.</span></div>\n<div class=\"c-line\" data-line=\"25\"><span class=\"c-no\">25</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"26\"><span class=\"c-no\">26</span><span class=\"c-src\">    Features:</span></div>\n<div class=\"c-line\" data-line=\"27\"><span class=\"c-no\">27</span><span class=\"c-src\">    - Lazy loading: Workspaces are created only when first requested</span></div>\n<div class=\"c-line\" data-line=\"28\"><span class=\"c-no\">28</span><span class=\"c-src\">    - Lifecycle management: Start, stop, reload workspaces</span></div>\n<div class=\"c-line\" data-line=\"29\"><span class=\"c-no\">29</span><span class=\"c-src\">    - Thread-safe: Uses <span class=\"c-kw\">async</span> lock <span class=\"c-kw\">for</span> concurrent access</span></div>\n<div class=\"c-line\" data-line=\"30\"><span class=\"c-no\">30</span><span class=\"c-src\">    - Hot reload: Reload individual workspaces without affecting others</span></div>\n<div class=\"c-line\" data-line=\"31\"><span class=\"c-no\">31</span><span class=\"c-src\">    - Parallel startup: Multiple agents start concurrently via</span></div>\n<div class=\"c-line\" data-line=\"32\"><span class=\"c-no\">32</span><span class=\"c-src\">      fine-grained locking (lock released during slow workspace init)</span></div>\n<div class=\"c-line\" data-line=\"33\"><span class=\"c-no\">33</span><span class=\"c-src\">    <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"34\"><span class=\"c-no\">34</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"35\"><span class=\"c-no\">35</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> __init__(<span class=\"c-kw\">self</span>):</span></div>\n<div class=\"c-line\" data-line=\"36\"><span class=\"c-no\">36</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Initialize multi-agent manager.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"37\"><span class=\"c-no\">37</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>.agents: Dict[str, Workspace] = {}</span></div>\n<div class=\"c-line\" data-line=\"38\"><span class=\"c-no\">38</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>._lock = asyncio.Lock()</span></div>\n<div class=\"c-line\" data-line=\"39\"><span class=\"c-no\">39</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>._pending_starts: Dict[str, asyncio.Event] = {}</span></div>\n<div class=\"c-line\" data-line=\"40\"><span class=\"c-no\">40</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>._cleanup_tasks: Set[asyncio.Task] = set()</span></div>\n<div class=\"c-line\" data-line=\"41\"><span class=\"c-no\">41</span><span class=\"c-src\">        logger.debug(<span class=\"c-str\">&quot;MultiAgentManager initialized&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"42\"><span class=\"c-no\">42</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"43\"><span class=\"c-no\">43</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> _create_workspace(</span></div>\n<div class=\"c-line\" data-line=\"44\"><span class=\"c-no\">44</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"45\"><span class=\"c-no\">45</span><span class=\"c-src\">        agent_id: str,</span></div>\n<div class=\"c-line\" data-line=\"46\"><span class=\"c-no\">46</span><span class=\"c-src\">        workspace_dir: str,</span></div>\n<div class=\"c-line\" data-line=\"47\"><span class=\"c-no\">47</span><span class=\"c-src\">    ) -&gt; Workspace:</span></div>\n<div class=\"c-line\" data-line=\"48\"><span class=\"c-no\">48</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Factory method <span class=\"c-kw\">for</span> workspace creation.</span></div>\n<div class=\"c-line\" data-line=\"49\"><span class=\"c-no\">49</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"50\"><span class=\"c-no\">50</span><span class=\"c-src\">        Overridden by WorkspaceRegistry.</span></div>\n<div class=\"c-line\" data-line=\"51\"><span class=\"c-no\">51</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"52\"><span class=\"c-no\">52</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> Workspace(agent_id=agent_id, workspace_dir=workspace_dir)</span></div>\n<div class=\"c-line\" data-line=\"53\"><span class=\"c-no\">53</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"54\"><span class=\"c-no\">54</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> get_agent(<span class=\"c-kw\">self</span>, agent_id: str) -&gt; Workspace:</span></div>\n<div class=\"c-line\" data-line=\"55\"><span class=\"c-no\">55</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Get agent workspace by ID (lazy loading <span class=\"c-kw\">with</span> dedup).</span></div>\n<div class=\"c-line\" data-line=\"56\"><span class=\"c-no\">56</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"57\"><span class=\"c-no\">57</span><span class=\"c-src\">        If workspace doesn&<span class=\"c-com\">#x27;t exist in memory, it will be created and started.</span></span></div>\n<div class=\"c-line\" data-line=\"58\"><span class=\"c-no\">58</span><span class=\"c-src\">        Multiple concurrent callers <span class=\"c-kw\">for</span> the same agent_id are coordinated:</span></div>\n<div class=\"c-line\" data-line=\"59\"><span class=\"c-no\">59</span><span class=\"c-src\">        the first caller creates the workspace <span class=\"c-kw\">while</span> others wait.</span></div>\n<div class=\"c-line\" data-line=\"60\"><span class=\"c-no\">60</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"61\"><span class=\"c-no\">61</span><span class=\"c-src\">        The lock <span class=\"c-kw\">is</span> only held briefly <span class=\"c-kw\">for</span> dict checks/mutations, <span class=\"c-kw\">not</span> during</span></div>\n<div class=\"c-line\" data-line=\"62\"><span class=\"c-no\">62</span><span class=\"c-src\">        the slow workspace startup, allowing parallel agent initialization.</span></div>\n<div class=\"c-line\" data-line=\"63\"><span class=\"c-no\">63</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"64\"><span class=\"c-no\">64</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"65\"><span class=\"c-no\">65</span><span class=\"c-src\">            agent_id: Agent ID to retrieve</span></div>\n<div class=\"c-line\" data-line=\"66\"><span class=\"c-no\">66</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"67\"><span class=\"c-no\">67</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"68\"><span class=\"c-no\">68</span><span class=\"c-src\">            Workspace: The requested workspace instance</span></div>\n<div class=\"c-line\" data-line=\"69\"><span class=\"c-no\">69</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"70\"><span class=\"c-no\">70</span><span class=\"c-src\">        Raises:</span></div>\n<div class=\"c-line\" data-line=\"71\"><span class=\"c-no\">71</span><span class=\"c-src\">            ConfigurationException: If agent ID <span class=\"c-kw\">not</span> found <span class=\"c-kw\">in</span> configuration</span></div>\n<div class=\"c-line\" data-line=\"72\"><span class=\"c-no\">72</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"73\"><span class=\"c-no\">73</span><span class=\"c-src\">        <span class=\"c-com\"># Fast path: already loaded (no lock)</span></span></div>\n<div class=\"c-line\" data-line=\"74\"><span class=\"c-no\">74</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> agent_id <span class=\"c-kw\">in</span> <span class=\"c-kw\">self</span>.agents:</span></div>\n<div class=\"c-line\" data-line=\"75\"><span class=\"c-no\">75</span><span class=\"c-src\">            logger.debug(f<span class=\"c-str\">&quot;Returning cached agent: {agent_id}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"76\"><span class=\"c-no\">76</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">self</span>.agents[agent_id]</span></div>\n<div class=\"c-line\" data-line=\"77\"><span class=\"c-no\">77</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"78\"><span class=\"c-no\">78</span><span class=\"c-src\">        should_start = <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"79\"><span class=\"c-no\">79</span><span class=\"c-src\">        event = <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"80\"><span class=\"c-no\">80</span><span class=\"c-src\">        agent_ref = <span class=\"c-kw\">None</span></span></div>\n<div class=\"c-line\" data-line=\"81\"><span class=\"c-no\">81</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"82\"><span class=\"c-no\">82</span><span class=\"c-src\">        <span class=\"c-kw\">async</span> <span class=\"c-kw\">with</span> <span class=\"c-kw\">self</span>._lock:</span></div>\n<div class=\"c-line\" data-line=\"83\"><span class=\"c-no\">83</span><span class=\"c-src\">            <span class=\"c-com\"># Re-check under lock</span></span></div>\n<div class=\"c-line\" data-line=\"84\"><span class=\"c-no\">84</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> agent_id <span class=\"c-kw\">in</span> <span class=\"c-kw\">self</span>.agents:</span></div>\n<div class=\"c-line\" data-line=\"85\"><span class=\"c-no\">85</span><span class=\"c-src\">                logger.debug(f<span class=\"c-str\">&quot;Returning cached agent: {agent_id}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"86\"><span class=\"c-no\">86</span><span class=\"c-src\">                <span class=\"c-kw\">return</span> <span class=\"c-kw\">self</span>.agents[agent_id]</span></div>\n<div class=\"c-line\" data-line=\"87\"><span class=\"c-no\">87</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"88\"><span class=\"c-no\">88</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> agent_id <span class=\"c-kw\">in</span> <span class=\"c-kw\">self</span>._pending_starts:</span></div>\n<div class=\"c-line\" data-line=\"89\"><span class=\"c-no\">89</span><span class=\"c-src\">                <span class=\"c-com\"># Another task is already starting this agent; wait for it</span></span></div>\n<div class=\"c-line\" data-line=\"90\"><span class=\"c-no\">90</span><span class=\"c-src\">                event = <span class=\"c-kw\">self</span>._pending_starts[agent_id]</span></div>\n<div class=\"c-line\" data-line=\"91\"><span class=\"c-no\">91</span><span class=\"c-src\">            <span class=\"c-kw\">else</span>:</span></div>\n<div class=\"c-line\" data-line=\"92\"><span class=\"c-no\">92</span><span class=\"c-src\">                <span class=\"c-com\"># We are the first caller — validate config and claim startup</span></span></div>\n<div class=\"c-line\" data-line=\"93\"><span class=\"c-no\">93</span><span class=\"c-src\">                config = load_config()</span></div>\n<div class=\"c-line\" data-line=\"94\"><span class=\"c-no\">94</span><span class=\"c-src\">                <span class=\"c-kw\">if</span> agent_id <span class=\"c-kw\">not</span> <span class=\"c-kw\">in</span> config.agents.profiles:</span></div>\n<div class=\"c-line\" data-line=\"95\"><span class=\"c-no\">95</span><span class=\"c-src\">                    <span class=\"c-kw\">raise</span> ConfigurationException(</span></div>\n<div class=\"c-line\" data-line=\"96\"><span class=\"c-no\">96</span><span class=\"c-src\">                        config_key=<span class=\"c-str\">&quot;agent&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"97\"><span class=\"c-no\">97</span><span class=\"c-src\">                        message=(</span></div>\n<div class=\"c-line\" data-line=\"98\"><span class=\"c-no\">98</span><span class=\"c-src\">                            f<span class=\"c-str\">&quot;Agent &#x27;{agent_id}&#x27; not found in configuration. &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"99\"><span class=\"c-no\">99</span><span class=\"c-src\">                            f<span class=\"c-str\">&quot;Available agents: &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"100\"><span class=\"c-no\">100</span><span class=\"c-src\">                            f<span class=\"c-str\">&quot;{list(config.agents.profiles.keys())}&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"101\"><span class=\"c-no\">101</span><span class=\"c-src\">                        ),</span></div>\n<div class=\"c-line\" data-line=\"102\"><span class=\"c-no\">102</span><span class=\"c-src\">                    )</span></div>\n<div class=\"c-line\" data-line=\"103\"><span class=\"c-no\">103</span><span class=\"c-src\">                agent_ref = config.agents.profiles[agent_id]</span></div>\n<div class=\"c-line\" data-line=\"104\"><span class=\"c-no\">104</span><span class=\"c-src\">                event = asyncio.Event()</span></div>\n<div class=\"c-line\" data-line=\"105\"><span class=\"c-no\">105</span><span class=\"c-src\">                <span class=\"c-kw\">self</span>._pending_starts[agent_id] = event</span></div>\n<div class=\"c-line\" data-line=\"106\"><span class=\"c-no\">106</span><span class=\"c-src\">                should_start = <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"107\"><span class=\"c-no\">107</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"108\"><span class=\"c-no\">108</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> should_start:</span></div>\n<div class=\"c-line\" data-line=\"109\"><span class=\"c-no\">109</span><span class=\"c-src\">            <span class=\"c-com\"># Wait for the in-progress startup to finish</span></span></div>\n<div class=\"c-line\" data-line=\"110\"><span class=\"c-no\">110</span><span class=\"c-src\">            <span class=\"c-kw\">await</span> event.wait()</span></div>\n<div class=\"c-line\" data-line=\"111\"><span class=\"c-no\">111</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> agent_id <span class=\"c-kw\">in</span> <span class=\"c-kw\">self</span>.agents:</span></div>\n<div class=\"c-line\" data-line=\"112\"><span class=\"c-no\">112</span><span class=\"c-src\">                logger.debug(f<span class=\"c-str\">&quot;Returning cached agent: {agent_id}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"113\"><span class=\"c-no\">113</span><span class=\"c-src\">                <span class=\"c-kw\">return</span> <span class=\"c-kw\">self</span>.agents[agent_id]</span></div>\n<div class=\"c-line\" data-line=\"114\"><span class=\"c-no\">114</span><span class=\"c-src\">            <span class=\"c-kw\">raise</span> ConfigurationException(</span></div>\n<div class=\"c-line\" data-line=\"115\"><span class=\"c-no\">115</span><span class=\"c-src\">                config_key=<span class=\"c-str\">&quot;agent&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"116\"><span class=\"c-no\">116</span><span class=\"c-src\">                message=f<span class=\"c-str\">&quot;Agent &#x27;{agent_id}&#x27; failed to initialize&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"117\"><span class=\"c-no\">117</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"118\"><span class=\"c-no\">118</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"119\"><span class=\"c-no\">119</span><span class=\"c-src\">        <span class=\"c-com\"># We are the starter — create outside the lock for parallelism</span></span></div>\n<div class=\"c-line\" data-line=\"120\"><span class=\"c-no\">120</span><span class=\"c-src\">        t0 = time.perf_counter()</span></div>\n<div class=\"c-line\" data-line=\"121\"><span class=\"c-no\">121</span><span class=\"c-src\">        logger.debug(f<span class=\"c-str\">&quot;Creating new workspace: {agent_id}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"122\"><span class=\"c-no\">122</span><span class=\"c-src\">        instance = <span class=\"c-kw\">self</span>._create_workspace(</span></div>\n<div class=\"c-line\" data-line=\"123\"><span class=\"c-no\">123</span><span class=\"c-src\">            agent_id=agent_id,</span></div>\n<div class=\"c-line\" data-line=\"124\"><span class=\"c-no\">124</span><span class=\"c-src\">            workspace_dir=agent_ref.workspace_dir,</span></div>\n<div class=\"c-line\" data-line=\"125\"><span class=\"c-no\">125</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"126\"><span class=\"c-no\">126</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"127\"><span class=\"c-no\">127</span><span class=\"c-src\">        <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"128\"><span class=\"c-no\">128</span><span class=\"c-src\">            <span class=\"c-kw\">await</span> instance.start()</span></div>\n<div class=\"c-line\" data-line=\"129\"><span class=\"c-no\">129</span><span class=\"c-src\">            instance.set_manager(<span class=\"c-kw\">self</span>)</span></div>\n<div class=\"c-line\" data-line=\"130\"><span class=\"c-no\">130</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"131\"><span class=\"c-no\">131</span><span class=\"c-src\">            <span class=\"c-kw\">async</span> <span class=\"c-kw\">with</span> <span class=\"c-kw\">self</span>._lock:</span></div>\n<div class=\"c-line\" data-line=\"132\"><span class=\"c-no\">132</span><span class=\"c-src\">                <span class=\"c-kw\">self</span>.agents[agent_id] = instance</span></div>\n<div class=\"c-line\" data-line=\"133\"><span class=\"c-no\">133</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"134\"><span class=\"c-no\">134</span><span class=\"c-src\">            elapsed = time.perf_counter() - t0</span></div>\n<div class=\"c-line\" data-line=\"135\"><span class=\"c-no\">135</span><span class=\"c-src\">            logger.debug(</span></div>\n<div class=\"c-line\" data-line=\"136\"><span class=\"c-no\">136</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;Workspace created and started: {agent_id} &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"137\"><span class=\"c-no\">137</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;({elapsed:.3f}s)&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"138\"><span class=\"c-no\">138</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"139\"><span class=\"c-no\">139</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"140\"><span class=\"c-no\">140</span><span class=\"c-src\">            <span class=\"c-com\"># Fire workspace_created hooks so plugins can provision</span></span></div>\n<div class=\"c-line\" data-line=\"141\"><span class=\"c-no\">141</span><span class=\"c-src\">            <span class=\"c-com\"># skills / config into the newly created workspace.</span></span></div>\n<div class=\"c-line\" data-line=\"142\"><span class=\"c-no\">142</span><span class=\"c-src\">            <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._fire_workspace_created_hooks(</span></div>\n<div class=\"c-line\" data-line=\"143\"><span class=\"c-no\">143</span><span class=\"c-src\">                {</span></div>\n<div class=\"c-line\" data-line=\"144\"><span class=\"c-no\">144</span><span class=\"c-src\">                    <span class=\"c-str\">&quot;agent_id&quot;</span>: agent_id,</span></div>\n<div class=\"c-line\" data-line=\"145\"><span class=\"c-no\">145</span><span class=\"c-src\">                    <span class=\"c-str\">&quot;workspace_dir&quot;</span>: str(agent_ref.workspace_dir),</span></div>\n<div class=\"c-line\" data-line=\"146\"><span class=\"c-no\">146</span><span class=\"c-src\">                },</span></div>\n<div class=\"c-line\" data-line=\"147\"><span class=\"c-no\">147</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"148\"><span class=\"c-no\">148</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"149\"><span class=\"c-no\">149</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> instance</span></div>\n<div class=\"c-line\" data-line=\"150\"><span class=\"c-no\">150</span><span class=\"c-src\">        <span class=\"c-kw\">except</span> Exception <span class=\"c-kw\">as</span> e:</span></div>\n<div class=\"c-line\" data-line=\"151\"><span class=\"c-no\">151</span><span class=\"c-src\">            logger.error(f<span class=\"c-str\">&quot;Failed to start workspace {agent_id}: {e}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"152\"><span class=\"c-no\">152</span><span class=\"c-src\">            <span class=\"c-kw\">raise</span></span></div>\n<div class=\"c-line\" data-line=\"153\"><span class=\"c-no\">153</span><span class=\"c-src\">        <span class=\"c-kw\">finally</span>:</span></div>\n<div class=\"c-line\" data-line=\"154\"><span class=\"c-no\">154</span><span class=\"c-src\">            <span class=\"c-com\"># Always clean up pending state and signal waiters</span></span></div>\n<div class=\"c-line\" data-line=\"155\"><span class=\"c-no\">155</span><span class=\"c-src\">            <span class=\"c-com\"># This handles cancellation (CancelledError) and all other cases</span></span></div>\n<div class=\"c-line\" data-line=\"156\"><span class=\"c-no\">156</span><span class=\"c-src\">            <span class=\"c-kw\">async</span> <span class=\"c-kw\">with</span> <span class=\"c-kw\">self</span>._lock:</span></div>\n<div class=\"c-line\" data-line=\"157\"><span class=\"c-no\">157</span><span class=\"c-src\">                <span class=\"c-kw\">self</span>._pending_starts.pop(agent_id, <span class=\"c-kw\">None</span>)</span></div>\n<div class=\"c-line\" data-line=\"158\"><span class=\"c-no\">158</span><span class=\"c-src\">            event.set()</span></div>\n<div class=\"c-line\" data-line=\"159\"><span class=\"c-no\">159</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"160\"><span class=\"c-no\">160</span><span class=\"c-src\">    @staticmethod</span></div>\n<div class=\"c-line\" data-line=\"161\"><span class=\"c-no\">161</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> _fire_workspace_created_hooks(workspace_info: dict) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"162\"><span class=\"c-no\">162</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Invoke all registered workspace_created hooks.</span></div>\n<div class=\"c-line\" data-line=\"163\"><span class=\"c-no\">163</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"164\"><span class=\"c-no\">164</span><span class=\"c-src\">        Supports both sync <span class=\"c-kw\">and</span> <span class=\"c-kw\">async</span> callbacks:</span></div>\n<div class=\"c-line\" data-line=\"165\"><span class=\"c-no\">165</span><span class=\"c-src\">        - Async callbacks are awaited directly.</span></div>\n<div class=\"c-line\" data-line=\"166\"><span class=\"c-no\">166</span><span class=\"c-src\">        - Sync callbacks are offloaded to a thread via</span></div>\n<div class=\"c-line\" data-line=\"167\"><span class=\"c-no\">167</span><span class=\"c-src\">          ``asyncio.to_thread`` so they never block the event loop.</span></div>\n<div class=\"c-line\" data-line=\"168\"><span class=\"c-no\">168</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"169\"><span class=\"c-no\">169</span><span class=\"c-src\">        Errors <span class=\"c-kw\">in</span> individual hooks are logged but do <span class=\"c-kw\">not</span> prevent</span></div>\n<div class=\"c-line\" data-line=\"170\"><span class=\"c-no\">170</span><span class=\"c-src\">        subsequent hooks <span class=\"c-kw\">from</span> running.</span></div>\n<div class=\"c-line\" data-line=\"171\"><span class=\"c-no\">171</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"172\"><span class=\"c-no\">172</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"173\"><span class=\"c-no\">173</span><span class=\"c-src\">            workspace_info: Dict <span class=\"c-kw\">with</span> at least ``agent_id`` <span class=\"c-kw\">and</span></span></div>\n<div class=\"c-line\" data-line=\"174\"><span class=\"c-no\">174</span><span class=\"c-src\">                ``workspace_dir`` keys.</span></div>\n<div class=\"c-line\" data-line=\"175\"><span class=\"c-no\">175</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"176\"><span class=\"c-no\">176</span><span class=\"c-src\">        <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"177\"><span class=\"c-no\">177</span><span class=\"c-src\">            <span class=\"c-kw\">from</span> ..plugins.registry <span class=\"c-kw\">import</span> PluginRegistry</span></div>\n<div class=\"c-line\" data-line=\"178\"><span class=\"c-no\">178</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"179\"><span class=\"c-no\">179</span><span class=\"c-src\">            hooks = PluginRegistry().get_workspace_created_hooks()</span></div>\n<div class=\"c-line\" data-line=\"180\"><span class=\"c-no\">180</span><span class=\"c-src\">        <span class=\"c-kw\">except</span> Exception:</span></div>\n<div class=\"c-line\" data-line=\"181\"><span class=\"c-no\">181</span><span class=\"c-src\">            <span class=\"c-com\"># Plugin system not initialised yet — nothing to do.</span></span></div>\n<div class=\"c-line\" data-line=\"182\"><span class=\"c-no\">182</span><span class=\"c-src\">            <span class=\"c-kw\">return</span></span></div>\n<div class=\"c-line\" data-line=\"183\"><span class=\"c-no\">183</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"184\"><span class=\"c-no\">184</span><span class=\"c-src\">        <span class=\"c-kw\">for</span> hook <span class=\"c-kw\">in</span> hooks:</span></div>\n<div class=\"c-line\" data-line=\"185\"><span class=\"c-no\">185</span><span class=\"c-src\">            <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"186\"><span class=\"c-no\">186</span><span class=\"c-src\">                callback = hook.callback</span></div>\n<div class=\"c-line\" data-line=\"187\"><span class=\"c-no\">187</span><span class=\"c-src\">                <span class=\"c-kw\">if</span> asyncio.iscoroutinefunction(callback):</span></div>\n<div class=\"c-line\" data-line=\"188\"><span class=\"c-no\">188</span><span class=\"c-src\">                    <span class=\"c-kw\">await</span> callback(workspace_info)</span></div>\n<div class=\"c-line\" data-line=\"189\"><span class=\"c-no\">189</span><span class=\"c-src\">                <span class=\"c-kw\">else</span>:</span></div>\n<div class=\"c-line\" data-line=\"190\"><span class=\"c-no\">190</span><span class=\"c-src\">                    result = <span class=\"c-kw\">await</span> asyncio.to_thread(callback, workspace_info)</span></div>\n<div class=\"c-line\" data-line=\"191\"><span class=\"c-no\">191</span><span class=\"c-src\">                    <span class=\"c-kw\">if</span> asyncio.iscoroutine(result) <span class=\"c-kw\">or</span> hasattr(</span></div>\n<div class=\"c-line\" data-line=\"192\"><span class=\"c-no\">192</span><span class=\"c-src\">                        result,</span></div>\n<div class=\"c-line\" data-line=\"193\"><span class=\"c-no\">193</span><span class=\"c-src\">                        <span class=\"c-str\">&quot;__await__&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"194\"><span class=\"c-no\">194</span><span class=\"c-src\">                    ):</span></div>\n<div class=\"c-line\" data-line=\"195\"><span class=\"c-no\">195</span><span class=\"c-src\">                        <span class=\"c-kw\">await</span> result</span></div>\n<div class=\"c-line\" data-line=\"196\"><span class=\"c-no\">196</span><span class=\"c-src\">            <span class=\"c-kw\">except</span> Exception <span class=\"c-kw\">as</span> exc:</span></div>\n<div class=\"c-line\" data-line=\"197\"><span class=\"c-no\">197</span><span class=\"c-src\">                logger.error(</span></div>\n<div class=\"c-line\" data-line=\"198\"><span class=\"c-no\">198</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;Error in workspace_created hook &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"199\"><span class=\"c-no\">199</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;&#x27;{hook.hook_name}&#x27; for plugin &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"200\"><span class=\"c-no\">200</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;&#x27;{hook.plugin_id}&#x27;: {exc}&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"201\"><span class=\"c-no\">201</span><span class=\"c-src\">                    exc_info=<span class=\"c-kw\">True</span>,</span></div>\n<div class=\"c-line\" data-line=\"202\"><span class=\"c-no\">202</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"203\"><span class=\"c-no\">203</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"204\"><span class=\"c-no\">204</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> _graceful_stop_old_instance(</span></div>\n<div class=\"c-line\" data-line=\"205\"><span class=\"c-no\">205</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>,</span></div>\n<div class=\"c-line\" data-line=\"206\"><span class=\"c-no\">206</span><span class=\"c-src\">        old_instance: Workspace,</span></div>\n<div class=\"c-line\" data-line=\"207\"><span class=\"c-no\">207</span><span class=\"c-src\">        agent_id: str,</span></div>\n<div class=\"c-line\" data-line=\"208\"><span class=\"c-no\">208</span><span class=\"c-src\">    ) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"209\"><span class=\"c-no\">209</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Gracefully stop old instance after checking <span class=\"c-kw\">for</span> active tasks.</span></div>\n<div class=\"c-line\" data-line=\"210\"><span class=\"c-no\">210</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"211\"><span class=\"c-no\">211</span><span class=\"c-src\">        If active tasks exist, schedule delayed cleanup <span class=\"c-kw\">in</span> background.</span></div>\n<div class=\"c-line\" data-line=\"212\"><span class=\"c-no\">212</span><span class=\"c-src\">        Otherwise, stop immediately.</span></div>\n<div class=\"c-line\" data-line=\"213\"><span class=\"c-no\">213</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"214\"><span class=\"c-no\">214</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"215\"><span class=\"c-no\">215</span><span class=\"c-src\">            old_instance: The old workspace instance to stop</span></div>\n<div class=\"c-line\" data-line=\"216\"><span class=\"c-no\">216</span><span class=\"c-src\">            agent_id: Agent ID <span class=\"c-kw\">for</span> logging</span></div>\n<div class=\"c-line\" data-line=\"217\"><span class=\"c-no\">217</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"218\"><span class=\"c-no\">218</span><span class=\"c-src\">        has_active = <span class=\"c-kw\">await</span> old_instance.task_tracker.has_active_tasks()</span></div>\n<div class=\"c-line\" data-line=\"219\"><span class=\"c-no\">219</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"220\"><span class=\"c-no\">220</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> has_active:</span></div>\n<div class=\"c-line\" data-line=\"221\"><span class=\"c-no\">221</span><span class=\"c-src\">            <span class=\"c-com\"># Active tasks - schedule delayed cleanup in background</span></span></div>\n<div class=\"c-line\" data-line=\"222\"><span class=\"c-no\">222</span><span class=\"c-src\">            active_tasks = <span class=\"c-kw\">await</span> old_instance.task_tracker.list_active_tasks()</span></div>\n<div class=\"c-line\" data-line=\"223\"><span class=\"c-no\">223</span><span class=\"c-src\">            logger.info(</span></div>\n<div class=\"c-line\" data-line=\"224\"><span class=\"c-no\">224</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;Old workspace instance has {len(active_tasks)} active &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"225\"><span class=\"c-no\">225</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;task(s): {active_tasks}. Scheduling delayed cleanup for &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"226\"><span class=\"c-no\">226</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;{agent_id}.&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"227\"><span class=\"c-no\">227</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"228\"><span class=\"c-no\">228</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"229\"><span class=\"c-no\">229</span><span class=\"c-src\">            <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> delayed_cleanup():</span></div>\n<div class=\"c-line\" data-line=\"230\"><span class=\"c-no\">230</span><span class=\"c-src\">                <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Wait for tasks to complete, then stop old instance.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"231\"><span class=\"c-no\">231</span><span class=\"c-src\">                <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"232\"><span class=\"c-no\">232</span><span class=\"c-src\">                    <span class=\"c-com\"># Wait up to 1 minutes for tasks to complete</span></span></div>\n<div class=\"c-line\" data-line=\"233\"><span class=\"c-no\">233</span><span class=\"c-src\">                    completed = <span class=\"c-kw\">await</span> old_instance.task_tracker.wait_all_done(</span></div>\n<div class=\"c-line\" data-line=\"234\"><span class=\"c-no\">234</span><span class=\"c-src\">                        timeout=60.0,</span></div>\n<div class=\"c-line\" data-line=\"235\"><span class=\"c-no\">235</span><span class=\"c-src\">                    )</span></div>\n<div class=\"c-line\" data-line=\"236\"><span class=\"c-no\">236</span><span class=\"c-src\">                    <span class=\"c-kw\">if</span> completed:</span></div>\n<div class=\"c-line\" data-line=\"237\"><span class=\"c-no\">237</span><span class=\"c-src\">                        logger.info(</span></div>\n<div class=\"c-line\" data-line=\"238\"><span class=\"c-no\">238</span><span class=\"c-src\">                            f<span class=\"c-str\">&quot;All tasks completed for old instance &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"239\"><span class=\"c-no\">239</span><span class=\"c-src\">                            f<span class=\"c-str\">&quot;{agent_id}. Stopping now.&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"240\"><span class=\"c-no\">240</span><span class=\"c-src\">                        )</span></div>\n<div class=\"c-line\" data-line=\"241\"><span class=\"c-no\">241</span><span class=\"c-src\">                    <span class=\"c-kw\">else</span>:</span></div>\n<div class=\"c-line\" data-line=\"242\"><span class=\"c-no\">242</span><span class=\"c-src\">                        logger.warning(</span></div>\n<div class=\"c-line\" data-line=\"243\"><span class=\"c-no\">243</span><span class=\"c-src\">                            f<span class=\"c-str\">&quot;Timeout waiting for tasks to complete for &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"244\"><span class=\"c-no\">244</span><span class=\"c-src\">                            f<span class=\"c-str\">&quot;{agent_id}. Forcing stop after 5 minutes.&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"245\"><span class=\"c-no\">245</span><span class=\"c-src\">                        )</span></div>\n<div class=\"c-line\" data-line=\"246\"><span class=\"c-no\">246</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"247\"><span class=\"c-no\">247</span><span class=\"c-src\">                    <span class=\"c-kw\">await</span> old_instance.stop(final=<span class=\"c-kw\">False</span>)</span></div>\n<div class=\"c-line\" data-line=\"248\"><span class=\"c-no\">248</span><span class=\"c-src\">                    logger.info(</span></div>\n<div class=\"c-line\" data-line=\"249\"><span class=\"c-no\">249</span><span class=\"c-src\">                        f<span class=\"c-str\">&quot;Old workspace instance stopped: {agent_id}. &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"250\"><span class=\"c-no\">250</span><span class=\"c-src\">                        f<span class=\"c-str\">&quot;Delayed cleanup completed.&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"251\"><span class=\"c-no\">251</span><span class=\"c-src\">                    )</span></div>\n<div class=\"c-line\" data-line=\"252\"><span class=\"c-no\">252</span><span class=\"c-src\">                <span class=\"c-kw\">except</span> Exception <span class=\"c-kw\">as</span> e:</span></div>\n<div class=\"c-line\" data-line=\"253\"><span class=\"c-no\">253</span><span class=\"c-src\">                    logger.warning(</span></div>\n<div class=\"c-line\" data-line=\"254\"><span class=\"c-no\">254</span><span class=\"c-src\">                        f<span class=\"c-str\">&quot;Error during delayed cleanup for {agent_id}: {e}. &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"255\"><span class=\"c-no\">255</span><span class=\"c-src\">                        f<span class=\"c-str\">&quot;New instance is serving requests.&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"256\"><span class=\"c-no\">256</span><span class=\"c-src\">                    )</span></div>\n<div class=\"c-line\" data-line=\"257\"><span class=\"c-no\">257</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"258\"><span class=\"c-no\">258</span><span class=\"c-src\">            <span class=\"c-com\"># Create background task for delayed cleanup and track it</span></span></div>\n<div class=\"c-line\" data-line=\"259\"><span class=\"c-no\">259</span><span class=\"c-src\">            cleanup_task = asyncio.create_task(delayed_cleanup())</span></div>\n<div class=\"c-line\" data-line=\"260\"><span class=\"c-no\">260</span><span class=\"c-src\">            <span class=\"c-kw\">self</span>._cleanup_tasks.add(cleanup_task)</span></div>\n<div class=\"c-line\" data-line=\"261\"><span class=\"c-no\">261</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"262\"><span class=\"c-no\">262</span><span class=\"c-src\">            <span class=\"c-kw\">def</span> _on_cleanup_done(task: asyncio.Task) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"263\"><span class=\"c-no\">263</span><span class=\"c-src\">                <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Remove task from tracking set and log errors.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"264\"><span class=\"c-no\">264</span><span class=\"c-src\">                <span class=\"c-kw\">self</span>._cleanup_tasks.discard(task)</span></div>\n<div class=\"c-line\" data-line=\"265\"><span class=\"c-no\">265</span><span class=\"c-src\">                <span class=\"c-kw\">if</span> task.cancelled():</span></div>\n<div class=\"c-line\" data-line=\"266\"><span class=\"c-no\">266</span><span class=\"c-src\">                    logger.info(</span></div>\n<div class=\"c-line\" data-line=\"267\"><span class=\"c-no\">267</span><span class=\"c-src\">                        f<span class=\"c-str\">&quot;Delayed cleanup task for {agent_id} was cancelled.&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"268\"><span class=\"c-no\">268</span><span class=\"c-src\">                    )</span></div>\n<div class=\"c-line\" data-line=\"269\"><span class=\"c-no\">269</span><span class=\"c-src\">                    <span class=\"c-kw\">return</span></span></div>\n<div class=\"c-line\" data-line=\"270\"><span class=\"c-no\">270</span><span class=\"c-src\">                exc = task.exception()</span></div>\n<div class=\"c-line\" data-line=\"271\"><span class=\"c-no\">271</span><span class=\"c-src\">                <span class=\"c-kw\">if</span> exc <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"272\"><span class=\"c-no\">272</span><span class=\"c-src\">                    logger.warning(</span></div>\n<div class=\"c-line\" data-line=\"273\"><span class=\"c-no\">273</span><span class=\"c-src\">                        f<span class=\"c-str\">&quot;Error in delayed cleanup task for {agent_id}: &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"274\"><span class=\"c-no\">274</span><span class=\"c-src\">                        f<span class=\"c-str\">&quot;{exc}.&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"275\"><span class=\"c-no\">275</span><span class=\"c-src\">                    )</span></div>\n<div class=\"c-line\" data-line=\"276\"><span class=\"c-no\">276</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"277\"><span class=\"c-no\">277</span><span class=\"c-src\">            cleanup_task.add_done_callback(_on_cleanup_done)</span></div>\n<div class=\"c-line\" data-line=\"278\"><span class=\"c-no\">278</span><span class=\"c-src\">            logger.info(</span></div>\n<div class=\"c-line\" data-line=\"279\"><span class=\"c-no\">279</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;Zero-downtime reload completed: {agent_id}. &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"280\"><span class=\"c-no\">280</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;Old instance cleanup scheduled in background.&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"281\"><span class=\"c-no\">281</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"282\"><span class=\"c-no\">282</span><span class=\"c-src\">        <span class=\"c-kw\">else</span>:</span></div>\n<div class=\"c-line\" data-line=\"283\"><span class=\"c-no\">283</span><span class=\"c-src\">            <span class=\"c-com\"># No active tasks - stop immediately</span></span></div>\n<div class=\"c-line\" data-line=\"284\"><span class=\"c-no\">284</span><span class=\"c-src\">            logger.debug(</span></div>\n<div class=\"c-line\" data-line=\"285\"><span class=\"c-no\">285</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;No active tasks in old instance {agent_id}. &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"286\"><span class=\"c-no\">286</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;Stopping immediately.&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"287\"><span class=\"c-no\">287</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"288\"><span class=\"c-no\">288</span><span class=\"c-src\">            <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"289\"><span class=\"c-no\">289</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> old_instance.stop(final=<span class=\"c-kw\">False</span>)</span></div>\n<div class=\"c-line\" data-line=\"290\"><span class=\"c-no\">290</span><span class=\"c-src\">                logger.info(</span></div>\n<div class=\"c-line\" data-line=\"291\"><span class=\"c-no\">291</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;Old workspace instance stopped: {agent_id}. &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"292\"><span class=\"c-no\">292</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;Zero-downtime reload completed.&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"293\"><span class=\"c-no\">293</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"294\"><span class=\"c-no\">294</span><span class=\"c-src\">            <span class=\"c-kw\">except</span> Exception <span class=\"c-kw\">as</span> e:</span></div>\n<div class=\"c-line\" data-line=\"295\"><span class=\"c-no\">295</span><span class=\"c-src\">                logger.warning(</span></div>\n<div class=\"c-line\" data-line=\"296\"><span class=\"c-no\">296</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;Failed to stop old workspace instance for &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"297\"><span class=\"c-no\">297</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;{agent_id}: {e}. &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"298\"><span class=\"c-no\">298</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;New instance is active and serving requests.&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"299\"><span class=\"c-no\">299</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"300\"><span class=\"c-no\">300</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"301\"><span class=\"c-no\">301</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> stop_agent(<span class=\"c-kw\">self</span>, agent_id: str) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"302\"><span class=\"c-no\">302</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Stop a specific agent instance.</span></div>\n<div class=\"c-line\" data-line=\"303\"><span class=\"c-no\">303</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"304\"><span class=\"c-no\">304</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"305\"><span class=\"c-no\">305</span><span class=\"c-src\">            agent_id: Agent ID to stop</span></div>\n<div class=\"c-line\" data-line=\"306\"><span class=\"c-no\">306</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"307\"><span class=\"c-no\">307</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"308\"><span class=\"c-no\">308</span><span class=\"c-src\">            bool: <span class=\"c-kw\">True</span> <span class=\"c-kw\">if</span> agent was stopped, <span class=\"c-kw\">False</span> <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> running</span></div>\n<div class=\"c-line\" data-line=\"309\"><span class=\"c-no\">309</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"310\"><span class=\"c-no\">310</span><span class=\"c-src\">        <span class=\"c-kw\">async</span> <span class=\"c-kw\">with</span> <span class=\"c-kw\">self</span>._lock:</span></div>\n<div class=\"c-line\" data-line=\"311\"><span class=\"c-no\">311</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> agent_id <span class=\"c-kw\">not</span> <span class=\"c-kw\">in</span> <span class=\"c-kw\">self</span>.agents:</span></div>\n<div class=\"c-line\" data-line=\"312\"><span class=\"c-no\">312</span><span class=\"c-src\">                logger.warning(f<span class=\"c-str\">&quot;Agent not running: {agent_id}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"313\"><span class=\"c-no\">313</span><span class=\"c-src\">                <span class=\"c-kw\">return</span> <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"314\"><span class=\"c-no\">314</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"315\"><span class=\"c-no\">315</span><span class=\"c-src\">            instance = <span class=\"c-kw\">self</span>.agents[agent_id]</span></div>\n<div class=\"c-line\" data-line=\"316\"><span class=\"c-no\">316</span><span class=\"c-src\">            <span class=\"c-kw\">await</span> instance.stop()</span></div>\n<div class=\"c-line\" data-line=\"317\"><span class=\"c-no\">317</span><span class=\"c-src\">            <span class=\"c-kw\">del</span> <span class=\"c-kw\">self</span>.agents[agent_id]</span></div>\n<div class=\"c-line\" data-line=\"318\"><span class=\"c-no\">318</span><span class=\"c-src\">            logger.info(f<span class=\"c-str\">&quot;Agent stopped and removed: {agent_id}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"319\"><span class=\"c-no\">319</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"320\"><span class=\"c-no\">320</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"321\"><span class=\"c-no\">321</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> reload_agent(<span class=\"c-kw\">self</span>, agent_id: str) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"322\"><span class=\"c-no\">322</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Reload a specific agent instance <span class=\"c-kw\">with</span> zero-downtime.</span></div>\n<div class=\"c-line\" data-line=\"323\"><span class=\"c-no\">323</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"324\"><span class=\"c-no\">324</span><span class=\"c-src\">        This method performs a seamless reload by:</span></div>\n<div class=\"c-line\" data-line=\"325\"><span class=\"c-no\">325</span><span class=\"c-src\">        1. Creating <span class=\"c-kw\">and</span> fully starting a new workspace instance (no lock)</span></div>\n<div class=\"c-line\" data-line=\"326\"><span class=\"c-no\">326</span><span class=\"c-src\">        2. Atomically replacing the old instance <span class=\"c-kw\">with</span> the new one (<span class=\"c-kw\">with</span> lock)</span></div>\n<div class=\"c-line\" data-line=\"327\"><span class=\"c-no\">327</span><span class=\"c-src\">        3. Gracefully stopping the old instance (no lock):</span></div>\n<div class=\"c-line\" data-line=\"328\"><span class=\"c-no\">328</span><span class=\"c-src\">           - If active tasks exist: schedule delayed cleanup <span class=\"c-kw\">in</span> background</span></div>\n<div class=\"c-line\" data-line=\"329\"><span class=\"c-no\">329</span><span class=\"c-src\">           - If no active tasks: stop immediately</span></div>\n<div class=\"c-line\" data-line=\"330\"><span class=\"c-no\">330</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"331\"><span class=\"c-no\">331</span><span class=\"c-src\">        The lock <span class=\"c-kw\">is</span> only held during the atomic swap to minimize blocking</span></div>\n<div class=\"c-line\" data-line=\"332\"><span class=\"c-no\">332</span><span class=\"c-src\">        time <span class=\"c-kw\">for</span> other agent operations.</span></div>\n<div class=\"c-line\" data-line=\"333\"><span class=\"c-no\">333</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"334\"><span class=\"c-no\">334</span><span class=\"c-src\">        This ensures that:</span></div>\n<div class=\"c-line\" data-line=\"335\"><span class=\"c-no\">335</span><span class=\"c-src\">        - New requests are immediately handled by the new instance</span></div>\n<div class=\"c-line\" data-line=\"336\"><span class=\"c-no\">336</span><span class=\"c-src\">        - Ongoing SSE/streaming tasks <span class=\"c-kw\">continue</span> uninterrupted</span></div>\n<div class=\"c-line\" data-line=\"337\"><span class=\"c-no\">337</span><span class=\"c-src\">        - Other agents remain accessible during reload</span></div>\n<div class=\"c-line\" data-line=\"338\"><span class=\"c-no\">338</span><span class=\"c-src\">        - The manager returns quickly without waiting <span class=\"c-kw\">for</span> old tasks</span></div>\n<div class=\"c-line\" data-line=\"339\"><span class=\"c-no\">339</span><span class=\"c-src\">        - Old instance <span class=\"c-kw\">is</span> automatically cleaned up after tasks complete</span></div>\n<div class=\"c-line\" data-line=\"340\"><span class=\"c-no\">340</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"341\"><span class=\"c-no\">341</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"342\"><span class=\"c-no\">342</span><span class=\"c-src\">            agent_id: Agent ID to reload</span></div>\n<div class=\"c-line\" data-line=\"343\"><span class=\"c-no\">343</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"344\"><span class=\"c-no\">344</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"345\"><span class=\"c-no\">345</span><span class=\"c-src\">            bool: <span class=\"c-kw\">True</span> <span class=\"c-kw\">if</span> agent was reloaded, <span class=\"c-kw\">False</span> <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> running</span></div>\n<div class=\"c-line\" data-line=\"346\"><span class=\"c-no\">346</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"347\"><span class=\"c-no\">347</span><span class=\"c-src\">        <span class=\"c-com\"># Step 1: Check if agent exists (quick check with lock)</span></span></div>\n<div class=\"c-line\" data-line=\"348\"><span class=\"c-no\">348</span><span class=\"c-src\">        <span class=\"c-kw\">async</span> <span class=\"c-kw\">with</span> <span class=\"c-kw\">self</span>._lock:</span></div>\n<div class=\"c-line\" data-line=\"349\"><span class=\"c-no\">349</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> agent_id <span class=\"c-kw\">not</span> <span class=\"c-kw\">in</span> <span class=\"c-kw\">self</span>.agents:</span></div>\n<div class=\"c-line\" data-line=\"350\"><span class=\"c-no\">350</span><span class=\"c-src\">                logger.debug(</span></div>\n<div class=\"c-line\" data-line=\"351\"><span class=\"c-no\">351</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;Agent not running, will be loaded on next &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"352\"><span class=\"c-no\">352</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;request: {agent_id}&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"353\"><span class=\"c-no\">353</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"354\"><span class=\"c-no\">354</span><span class=\"c-src\">                <span class=\"c-kw\">return</span> <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"355\"><span class=\"c-no\">355</span><span class=\"c-src\">            old_instance = <span class=\"c-kw\">self</span>.agents[agent_id]</span></div>\n<div class=\"c-line\" data-line=\"356\"><span class=\"c-no\">356</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"357\"><span class=\"c-no\">357</span><span class=\"c-src\">        logger.info(f<span class=\"c-str\">&quot;Reloading agent (zero-downtime): {agent_id}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"358\"><span class=\"c-no\">358</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"359\"><span class=\"c-no\">359</span><span class=\"c-src\">        <span class=\"c-com\"># Step 1.5: Stop old config watcher (no-op if it triggered</span></span></div>\n<div class=\"c-line\" data-line=\"360\"><span class=\"c-no\">360</span><span class=\"c-src\">        <span class=\"c-com\"># this reload, since it already disabled itself).</span></span></div>\n<div class=\"c-line\" data-line=\"361\"><span class=\"c-no\">361</span><span class=\"c-src\">        <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"362\"><span class=\"c-no\">362</span><span class=\"c-src\">            <span class=\"c-com\"># pylint: disable=protected-access</span></span></div>\n<div class=\"c-line\" data-line=\"363\"><span class=\"c-no\">363</span><span class=\"c-src\">            old_watcher = old_instance._service_manager.services.get(</span></div>\n<div class=\"c-line\" data-line=\"364\"><span class=\"c-no\">364</span><span class=\"c-src\">                <span class=\"c-str\">&quot;agent_config_watcher&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"365\"><span class=\"c-no\">365</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"366\"><span class=\"c-no\">366</span><span class=\"c-src\">            <span class=\"c-com\"># pylint: enable=protected-access</span></span></div>\n<div class=\"c-line\" data-line=\"367\"><span class=\"c-no\">367</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> old_watcher <span class=\"c-kw\">is</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"368\"><span class=\"c-no\">368</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> old_watcher.stop()</span></div>\n<div class=\"c-line\" data-line=\"369\"><span class=\"c-no\">369</span><span class=\"c-src\">        <span class=\"c-kw\">except</span> Exception <span class=\"c-kw\">as</span> stop_err:</span></div>\n<div class=\"c-line\" data-line=\"370\"><span class=\"c-no\">370</span><span class=\"c-src\">            logger.warning(</span></div>\n<div class=\"c-line\" data-line=\"371\"><span class=\"c-no\">371</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;Failed to stop old AgentConfigWatcher for &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"372\"><span class=\"c-no\">372</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;{agent_id}: {stop_err}.&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"373\"><span class=\"c-no\">373</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"374\"><span class=\"c-no\">374</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"375\"><span class=\"c-no\">375</span><span class=\"c-src\">        <span class=\"c-com\"># Step 2: Load configuration (outside lock)</span></span></div>\n<div class=\"c-line\" data-line=\"376\"><span class=\"c-no\">376</span><span class=\"c-src\">        config = load_config()</span></div>\n<div class=\"c-line\" data-line=\"377\"><span class=\"c-no\">377</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> agent_id <span class=\"c-kw\">not</span> <span class=\"c-kw\">in</span> config.agents.profiles:</span></div>\n<div class=\"c-line\" data-line=\"378\"><span class=\"c-no\">378</span><span class=\"c-src\">            logger.error(</span></div>\n<div class=\"c-line\" data-line=\"379\"><span class=\"c-no\">379</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;Agent &#x27;{agent_id}&#x27; not found in configuration &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"380\"><span class=\"c-no\">380</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;during reload&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"381\"><span class=\"c-no\">381</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"382\"><span class=\"c-no\">382</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"383\"><span class=\"c-no\">383</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"384\"><span class=\"c-no\">384</span><span class=\"c-src\">        agent_ref = config.agents.profiles[agent_id]</span></div>\n<div class=\"c-line\" data-line=\"385\"><span class=\"c-no\">385</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"386\"><span class=\"c-no\">386</span><span class=\"c-src\">        <span class=\"c-com\"># Step 3: Create and start new workspace instance (outside lock)</span></span></div>\n<div class=\"c-line\" data-line=\"387\"><span class=\"c-no\">387</span><span class=\"c-src\">        <span class=\"c-com\"># This is the slow part, but doesn&#x27;t block other agents</span></span></div>\n<div class=\"c-line\" data-line=\"388\"><span class=\"c-no\">388</span><span class=\"c-src\">        logger.info(f<span class=\"c-str\">&quot;Creating new workspace instance: {agent_id}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"389\"><span class=\"c-no\">389</span><span class=\"c-src\">        new_instance = <span class=\"c-kw\">self</span>._create_workspace(</span></div>\n<div class=\"c-line\" data-line=\"390\"><span class=\"c-no\">390</span><span class=\"c-src\">            agent_id=agent_id,</span></div>\n<div class=\"c-line\" data-line=\"391\"><span class=\"c-no\">391</span><span class=\"c-src\">            workspace_dir=agent_ref.workspace_dir,</span></div>\n<div class=\"c-line\" data-line=\"392\"><span class=\"c-no\">392</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"393\"><span class=\"c-no\">393</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"394\"><span class=\"c-no\">394</span><span class=\"c-src\">        <span class=\"c-com\"># Step 3.5: Set reusable components from old instance (if any)</span></span></div>\n<div class=\"c-line\" data-line=\"395\"><span class=\"c-no\">395</span><span class=\"c-src\">        <span class=\"c-kw\">async</span> <span class=\"c-kw\">with</span> <span class=\"c-kw\">self</span>._lock:</span></div>\n<div class=\"c-line\" data-line=\"396\"><span class=\"c-no\">396</span><span class=\"c-src\">            old_instance = <span class=\"c-kw\">self</span>.agents.get(agent_id)</span></div>\n<div class=\"c-line\" data-line=\"397\"><span class=\"c-no\">397</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"398\"><span class=\"c-no\">398</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> old_instance:</span></div>\n<div class=\"c-line\" data-line=\"399\"><span class=\"c-no\">399</span><span class=\"c-src\">            <span class=\"c-com\"># Get all reusable services from old instance&#x27;s ServiceManager</span></span></div>\n<div class=\"c-line\" data-line=\"400\"><span class=\"c-no\">400</span><span class=\"c-src\">            <span class=\"c-com\"># pylint: disable=protected-access</span></span></div>\n<div class=\"c-line\" data-line=\"401\"><span class=\"c-no\">401</span><span class=\"c-src\">            reusable = old_instance._service_manager.get_reusable_services()</span></div>\n<div class=\"c-line\" data-line=\"402\"><span class=\"c-no\">402</span><span class=\"c-src\">            <span class=\"c-com\"># pylint: enable=protected-access</span></span></div>\n<div class=\"c-line\" data-line=\"403\"><span class=\"c-no\">403</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"404\"><span class=\"c-no\">404</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> reusable:</span></div>\n<div class=\"c-line\" data-line=\"405\"><span class=\"c-no\">405</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> new_instance.set_reusable_components(reusable)</span></div>\n<div class=\"c-line\" data-line=\"406\"><span class=\"c-no\">406</span><span class=\"c-src\">                logger.info(</span></div>\n<div class=\"c-line\" data-line=\"407\"><span class=\"c-no\">407</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;Set reusable components for {agent_id}: &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"408\"><span class=\"c-no\">408</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;{list(reusable.keys())}&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"409\"><span class=\"c-no\">409</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"410\"><span class=\"c-no\">410</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"411\"><span class=\"c-no\">411</span><span class=\"c-src\">        <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"412\"><span class=\"c-no\">412</span><span class=\"c-src\">            <span class=\"c-kw\">await</span> new_instance.start()</span></div>\n<div class=\"c-line\" data-line=\"413\"><span class=\"c-no\">413</span><span class=\"c-src\">            new_instance.set_manager(<span class=\"c-kw\">self</span>)  <span class=\"c-com\"># Set manager reference</span></span></div>\n<div class=\"c-line\" data-line=\"414\"><span class=\"c-no\">414</span><span class=\"c-src\">            logger.info(f<span class=\"c-str\">&quot;New workspace instance started: {agent_id}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"415\"><span class=\"c-no\">415</span><span class=\"c-src\">        <span class=\"c-kw\">except</span> Exception <span class=\"c-kw\">as</span> e:</span></div>\n<div class=\"c-line\" data-line=\"416\"><span class=\"c-no\">416</span><span class=\"c-src\">            logger.exception(</span></div>\n<div class=\"c-line\" data-line=\"417\"><span class=\"c-no\">417</span><span class=\"c-src\">                f<span class=\"c-str\">&quot;Failed to start new workspace instance for {agent_id}: {e}&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"418\"><span class=\"c-no\">418</span><span class=\"c-src\">            )</span></div>\n<div class=\"c-line\" data-line=\"419\"><span class=\"c-no\">419</span><span class=\"c-src\">            <span class=\"c-com\"># Try to clean up the failed new instance</span></span></div>\n<div class=\"c-line\" data-line=\"420\"><span class=\"c-no\">420</span><span class=\"c-src\">            <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"421\"><span class=\"c-no\">421</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> new_instance.stop()</span></div>\n<div class=\"c-line\" data-line=\"422\"><span class=\"c-no\">422</span><span class=\"c-src\">            <span class=\"c-kw\">except</span> Exception:</span></div>\n<div class=\"c-line\" data-line=\"423\"><span class=\"c-no\">423</span><span class=\"c-src\">                <span class=\"c-kw\">pass</span>  <span class=\"c-com\"># Best effort cleanup</span></span></div>\n<div class=\"c-line\" data-line=\"424\"><span class=\"c-no\">424</span><span class=\"c-src\">            <span class=\"c-com\"># Old instance is still running and serving requests</span></span></div>\n<div class=\"c-line\" data-line=\"425\"><span class=\"c-no\">425</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"426\"><span class=\"c-no\">426</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"427\"><span class=\"c-no\">427</span><span class=\"c-src\">        <span class=\"c-com\"># Step 4: Atomic swap (minimal lock time)</span></span></div>\n<div class=\"c-line\" data-line=\"428\"><span class=\"c-no\">428</span><span class=\"c-src\">        <span class=\"c-com\"># From this point, reload is considered successful</span></span></div>\n<div class=\"c-line\" data-line=\"429\"><span class=\"c-no\">429</span><span class=\"c-src\">        <span class=\"c-kw\">async</span> <span class=\"c-kw\">with</span> <span class=\"c-kw\">self</span>._lock:</span></div>\n<div class=\"c-line\" data-line=\"430\"><span class=\"c-no\">430</span><span class=\"c-src\">            <span class=\"c-com\"># Double-check agent still exists</span></span></div>\n<div class=\"c-line\" data-line=\"431\"><span class=\"c-no\">431</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> agent_id <span class=\"c-kw\">not</span> <span class=\"c-kw\">in</span> <span class=\"c-kw\">self</span>.agents:</span></div>\n<div class=\"c-line\" data-line=\"432\"><span class=\"c-no\">432</span><span class=\"c-src\">                logger.warning(</span></div>\n<div class=\"c-line\" data-line=\"433\"><span class=\"c-no\">433</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;Agent {agent_id} was removed during reload, &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"434\"><span class=\"c-no\">434</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;stopping new instance&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"435\"><span class=\"c-no\">435</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"436\"><span class=\"c-no\">436</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> new_instance.stop()</span></div>\n<div class=\"c-line\" data-line=\"437\"><span class=\"c-no\">437</span><span class=\"c-src\">                <span class=\"c-kw\">return</span> <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"438\"><span class=\"c-no\">438</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"439\"><span class=\"c-no\">439</span><span class=\"c-src\">            <span class=\"c-com\"># Swap instances atomically</span></span></div>\n<div class=\"c-line\" data-line=\"440\"><span class=\"c-no\">440</span><span class=\"c-src\">            old_instance = <span class=\"c-kw\">self</span>.agents[agent_id]</span></div>\n<div class=\"c-line\" data-line=\"441\"><span class=\"c-no\">441</span><span class=\"c-src\">            <span class=\"c-kw\">self</span>.agents[agent_id] = new_instance</span></div>\n<div class=\"c-line\" data-line=\"442\"><span class=\"c-no\">442</span><span class=\"c-src\">            logger.info(f<span class=\"c-str\">&quot;Workspace instance replaced: {agent_id}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"443\"><span class=\"c-no\">443</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"444\"><span class=\"c-no\">444</span><span class=\"c-src\">        <span class=\"c-com\"># Step 5: Gracefully stop old instance (outside lock)</span></span></div>\n<div class=\"c-line\" data-line=\"445\"><span class=\"c-no\">445</span><span class=\"c-src\">        <span class=\"c-com\"># Delegates to helper method to avoid too-many-statements</span></span></div>\n<div class=\"c-line\" data-line=\"446\"><span class=\"c-no\">446</span><span class=\"c-src\">        <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>._graceful_stop_old_instance(old_instance, agent_id)</span></div>\n<div class=\"c-line\" data-line=\"447\"><span class=\"c-no\">447</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"448\"><span class=\"c-no\">448</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"449\"><span class=\"c-no\">449</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"450\"><span class=\"c-no\">450</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> cancel_all_cleanup_tasks(<span class=\"c-kw\">self</span>) -&gt; <span class=\"c-kw\">None</span>:</span></div>\n<div class=\"c-line\" data-line=\"451\"><span class=\"c-no\">451</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Cancel <span class=\"c-kw\">and</span> <span class=\"c-kw\">await</span> all pending delayed cleanup tasks.</span></div>\n<div class=\"c-line\" data-line=\"452\"><span class=\"c-no\">452</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"453\"><span class=\"c-no\">453</span><span class=\"c-src\">        This ensures that any <span class=\"c-kw\">in</span>-progress background cleanups are either</span></div>\n<div class=\"c-line\" data-line=\"454\"><span class=\"c-no\">454</span><span class=\"c-src\">        completed <span class=\"c-kw\">or</span> cleanly cancelled before the manager <span class=\"c-kw\">is</span> torn down.</span></div>\n<div class=\"c-line\" data-line=\"455\"><span class=\"c-no\">455</span><span class=\"c-src\">        Called by stop_all() during shutdown.</span></div>\n<div class=\"c-line\" data-line=\"456\"><span class=\"c-no\">456</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"457\"><span class=\"c-no\">457</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> <span class=\"c-kw\">self</span>._cleanup_tasks:</span></div>\n<div class=\"c-line\" data-line=\"458\"><span class=\"c-no\">458</span><span class=\"c-src\">            <span class=\"c-kw\">return</span></span></div>\n<div class=\"c-line\" data-line=\"459\"><span class=\"c-no\">459</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"460\"><span class=\"c-no\">460</span><span class=\"c-src\">        logger.info(</span></div>\n<div class=\"c-line\" data-line=\"461\"><span class=\"c-no\">461</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;Cancelling {len(self._cleanup_tasks)} pending cleanup &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"462\"><span class=\"c-no\">462</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;task(s)...&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"463\"><span class=\"c-no\">463</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"464\"><span class=\"c-no\">464</span><span class=\"c-src\">        tasks = list(<span class=\"c-kw\">self</span>._cleanup_tasks)</span></div>\n<div class=\"c-line\" data-line=\"465\"><span class=\"c-no\">465</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>._cleanup_tasks.clear()</span></div>\n<div class=\"c-line\" data-line=\"466\"><span class=\"c-no\">466</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"467\"><span class=\"c-no\">467</span><span class=\"c-src\">        <span class=\"c-kw\">for</span> task <span class=\"c-kw\">in</span> tasks:</span></div>\n<div class=\"c-line\" data-line=\"468\"><span class=\"c-no\">468</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> task.done():</span></div>\n<div class=\"c-line\" data-line=\"469\"><span class=\"c-no\">469</span><span class=\"c-src\">                task.cancel()</span></div>\n<div class=\"c-line\" data-line=\"470\"><span class=\"c-no\">470</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"471\"><span class=\"c-no\">471</span><span class=\"c-src\">        <span class=\"c-com\"># Await completion of all tasks, collecting exceptions</span></span></div>\n<div class=\"c-line\" data-line=\"472\"><span class=\"c-no\">472</span><span class=\"c-src\">        <span class=\"c-kw\">await</span> asyncio.gather(*tasks, return_exceptions=<span class=\"c-kw\">True</span>)</span></div>\n<div class=\"c-line\" data-line=\"473\"><span class=\"c-no\">473</span><span class=\"c-src\">        logger.info(<span class=\"c-str\">&quot;All cleanup tasks cancelled/completed&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"474\"><span class=\"c-no\">474</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"475\"><span class=\"c-no\">475</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> stop_all(<span class=\"c-kw\">self</span>):</span></div>\n<div class=\"c-line\" data-line=\"476\"><span class=\"c-no\">476</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Stop all agent instances concurrently.</span></div>\n<div class=\"c-line\" data-line=\"477\"><span class=\"c-no\">477</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"478\"><span class=\"c-no\">478</span><span class=\"c-src\">        Called during application shutdown to clean up resources.</span></div>\n<div class=\"c-line\" data-line=\"479\"><span class=\"c-no\">479</span><span class=\"c-src\">        Cancels any pending delayed cleanup tasks <span class=\"c-kw\">and</span> stops all</span></div>\n<div class=\"c-line\" data-line=\"480\"><span class=\"c-no\">480</span><span class=\"c-src\">        agents <span class=\"c-kw\">in</span> parallel via asyncio.gather.</span></div>\n<div class=\"c-line\" data-line=\"481\"><span class=\"c-no\">481</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"482\"><span class=\"c-no\">482</span><span class=\"c-src\">        logger.info(</span></div>\n<div class=\"c-line\" data-line=\"483\"><span class=\"c-no\">483</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;Stopping all agents ({len(self.agents)} running)...&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"484\"><span class=\"c-no\">484</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"485\"><span class=\"c-no\">485</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"486\"><span class=\"c-no\">486</span><span class=\"c-src\">        <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>.cancel_all_cleanup_tasks()</span></div>\n<div class=\"c-line\" data-line=\"487\"><span class=\"c-no\">487</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"488\"><span class=\"c-no\">488</span><span class=\"c-src\">        <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> _stop_one(agent_id: str, instance: Workspace):</span></div>\n<div class=\"c-line\" data-line=\"489\"><span class=\"c-no\">489</span><span class=\"c-src\">            <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"490\"><span class=\"c-no\">490</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> instance.stop()</span></div>\n<div class=\"c-line\" data-line=\"491\"><span class=\"c-no\">491</span><span class=\"c-src\">                logger.debug(f<span class=\"c-str\">&quot;Agent stopped: {agent_id}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"492\"><span class=\"c-no\">492</span><span class=\"c-src\">            <span class=\"c-kw\">except</span> Exception <span class=\"c-kw\">as</span> e:</span></div>\n<div class=\"c-line\" data-line=\"493\"><span class=\"c-no\">493</span><span class=\"c-src\">                logger.error(</span></div>\n<div class=\"c-line\" data-line=\"494\"><span class=\"c-no\">494</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;Error stopping agent {agent_id}: {e}&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"495\"><span class=\"c-no\">495</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"496\"><span class=\"c-no\">496</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"497\"><span class=\"c-no\">497</span><span class=\"c-src\">        <span class=\"c-kw\">await</span> asyncio.gather(</span></div>\n<div class=\"c-line\" data-line=\"498\"><span class=\"c-no\">498</span><span class=\"c-src\">            *(_stop_one(aid, inst) <span class=\"c-kw\">for</span> aid, inst <span class=\"c-kw\">in</span> <span class=\"c-kw\">self</span>.agents.items()),</span></div>\n<div class=\"c-line\" data-line=\"499\"><span class=\"c-no\">499</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"500\"><span class=\"c-no\">500</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"501\"><span class=\"c-no\">501</span><span class=\"c-src\">        <span class=\"c-kw\">self</span>.agents.clear()</span></div>\n<div class=\"c-line\" data-line=\"502\"><span class=\"c-no\">502</span><span class=\"c-src\">        logger.info(<span class=\"c-str\">&quot;All agents stopped&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"503\"><span class=\"c-no\">503</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"504\"><span class=\"c-no\">504</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> list_loaded_agents(<span class=\"c-kw\">self</span>) -&gt; list[str]:</span></div>\n<div class=\"c-line\" data-line=\"505\"><span class=\"c-no\">505</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;List currently loaded agent IDs.</span></div>\n<div class=\"c-line\" data-line=\"506\"><span class=\"c-no\">506</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"507\"><span class=\"c-no\">507</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"508\"><span class=\"c-no\">508</span><span class=\"c-src\">            list[str]: List of loaded agent IDs</span></div>\n<div class=\"c-line\" data-line=\"509\"><span class=\"c-no\">509</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"510\"><span class=\"c-no\">510</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> list(<span class=\"c-kw\">self</span>.agents.keys())</span></div>\n<div class=\"c-line\" data-line=\"511\"><span class=\"c-no\">511</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"512\"><span class=\"c-no\">512</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> is_agent_loaded(<span class=\"c-kw\">self</span>, agent_id: str) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"513\"><span class=\"c-no\">513</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Check <span class=\"c-kw\">if</span> agent <span class=\"c-kw\">is</span> currently loaded.</span></div>\n<div class=\"c-line\" data-line=\"514\"><span class=\"c-no\">514</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"515\"><span class=\"c-no\">515</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"516\"><span class=\"c-no\">516</span><span class=\"c-src\">            agent_id: Agent ID to check</span></div>\n<div class=\"c-line\" data-line=\"517\"><span class=\"c-no\">517</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"518\"><span class=\"c-no\">518</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"519\"><span class=\"c-no\">519</span><span class=\"c-src\">            bool: <span class=\"c-kw\">True</span> <span class=\"c-kw\">if</span> agent <span class=\"c-kw\">is</span> loaded <span class=\"c-kw\">and</span> running</span></div>\n<div class=\"c-line\" data-line=\"520\"><span class=\"c-no\">520</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"521\"><span class=\"c-no\">521</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> agent_id <span class=\"c-kw\">in</span> <span class=\"c-kw\">self</span>.agents</span></div>\n<div class=\"c-line\" data-line=\"522\"><span class=\"c-no\">522</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"523\"><span class=\"c-no\">523</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> preload_agent(<span class=\"c-kw\">self</span>, agent_id: str) -&gt; bool:</span></div>\n<div class=\"c-line\" data-line=\"524\"><span class=\"c-no\">524</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Preload an agent instance during startup.</span></div>\n<div class=\"c-line\" data-line=\"525\"><span class=\"c-no\">525</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"526\"><span class=\"c-no\">526</span><span class=\"c-src\">        Args:</span></div>\n<div class=\"c-line\" data-line=\"527\"><span class=\"c-no\">527</span><span class=\"c-src\">            agent_id: Agent ID to preload</span></div>\n<div class=\"c-line\" data-line=\"528\"><span class=\"c-no\">528</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"529\"><span class=\"c-no\">529</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"530\"><span class=\"c-no\">530</span><span class=\"c-src\">            bool: <span class=\"c-kw\">True</span> <span class=\"c-kw\">if</span> successfully preloaded, <span class=\"c-kw\">False</span> <span class=\"c-kw\">if</span> failed</span></div>\n<div class=\"c-line\" data-line=\"531\"><span class=\"c-no\">531</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"532\"><span class=\"c-no\">532</span><span class=\"c-src\">        <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"533\"><span class=\"c-no\">533</span><span class=\"c-src\">            <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>.get_agent(agent_id)</span></div>\n<div class=\"c-line\" data-line=\"534\"><span class=\"c-no\">534</span><span class=\"c-src\">            logger.info(f<span class=\"c-str\">&quot;Successfully preloaded agent: {agent_id}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"535\"><span class=\"c-no\">535</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">True</span></span></div>\n<div class=\"c-line\" data-line=\"536\"><span class=\"c-no\">536</span><span class=\"c-src\">        <span class=\"c-kw\">except</span> Exception <span class=\"c-kw\">as</span> e:</span></div>\n<div class=\"c-line\" data-line=\"537\"><span class=\"c-no\">537</span><span class=\"c-src\">            logger.error(f<span class=\"c-str\">&quot;Failed to preload agent {agent_id}: {e}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"538\"><span class=\"c-no\">538</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> <span class=\"c-kw\">False</span></span></div>\n<div class=\"c-line\" data-line=\"539\"><span class=\"c-no\">539</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"540\"><span class=\"c-no\">540</span><span class=\"c-src\">    <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> start_all_configured_agents(<span class=\"c-kw\">self</span>) -&gt; dict[str, bool]:</span></div>\n<div class=\"c-line\" data-line=\"541\"><span class=\"c-no\">541</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;Start all enabled agents defined <span class=\"c-kw\">in</span> configuration concurrently.</span></div>\n<div class=\"c-line\" data-line=\"542\"><span class=\"c-no\">542</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"543\"><span class=\"c-no\">543</span><span class=\"c-src\">        Only agents <span class=\"c-kw\">with</span> enabled=<span class=\"c-kw\">True</span> will be started.</span></div>\n<div class=\"c-line\" data-line=\"544\"><span class=\"c-no\">544</span><span class=\"c-src\">        Disabled agents are skipped to save resources.</span></div>\n<div class=\"c-line\" data-line=\"545\"><span class=\"c-no\">545</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"546\"><span class=\"c-no\">546</span><span class=\"c-src\">        Agents are started truly <span class=\"c-kw\">in</span> parallel: get_agent() only holds the</span></div>\n<div class=\"c-line\" data-line=\"547\"><span class=\"c-no\">547</span><span class=\"c-src\">        manager lock briefly <span class=\"c-kw\">for</span> dict checks, releasing it during the slow</span></div>\n<div class=\"c-line\" data-line=\"548\"><span class=\"c-no\">548</span><span class=\"c-src\">        workspace initialization.</span></div>\n<div class=\"c-line\" data-line=\"549\"><span class=\"c-no\">549</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"550\"><span class=\"c-no\">550</span><span class=\"c-src\">        Returns:</span></div>\n<div class=\"c-line\" data-line=\"551\"><span class=\"c-no\">551</span><span class=\"c-src\">            dict[str, bool]: Mapping of agent_id to success status</span></div>\n<div class=\"c-line\" data-line=\"552\"><span class=\"c-no\">552</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span>&quot;</span></div>\n<div class=\"c-line\" data-line=\"553\"><span class=\"c-no\">553</span><span class=\"c-src\">        config = load_config()</span></div>\n<div class=\"c-line\" data-line=\"554\"><span class=\"c-no\">554</span><span class=\"c-src\">        <span class=\"c-com\"># Filter only enabled agents</span></span></div>\n<div class=\"c-line\" data-line=\"555\"><span class=\"c-no\">555</span><span class=\"c-src\">        enabled_agents = {</span></div>\n<div class=\"c-line\" data-line=\"556\"><span class=\"c-no\">556</span><span class=\"c-src\">            agent_id: ref</span></div>\n<div class=\"c-line\" data-line=\"557\"><span class=\"c-no\">557</span><span class=\"c-src\">            <span class=\"c-kw\">for</span> agent_id, ref <span class=\"c-kw\">in</span> config.agents.profiles.items()</span></div>\n<div class=\"c-line\" data-line=\"558\"><span class=\"c-no\">558</span><span class=\"c-src\">            <span class=\"c-kw\">if</span> getattr(ref, <span class=\"c-str\">&quot;enabled&quot;</span>, <span class=\"c-kw\">True</span>)</span></div>\n<div class=\"c-line\" data-line=\"559\"><span class=\"c-no\">559</span><span class=\"c-src\">        }</span></div>\n<div class=\"c-line\" data-line=\"560\"><span class=\"c-no\">560</span><span class=\"c-src\">        agent_ids = list(enabled_agents.keys())</span></div>\n<div class=\"c-line\" data-line=\"561\"><span class=\"c-no\">561</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"562\"><span class=\"c-no\">562</span><span class=\"c-src\">        <span class=\"c-kw\">if</span> <span class=\"c-kw\">not</span> agent_ids:</span></div>\n<div class=\"c-line\" data-line=\"563\"><span class=\"c-no\">563</span><span class=\"c-src\">            logger.warning(<span class=\"c-str\">&quot;No enabled agents configured in config&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"564\"><span class=\"c-no\">564</span><span class=\"c-src\">            <span class=\"c-kw\">return</span> {}</span></div>\n<div class=\"c-line\" data-line=\"565\"><span class=\"c-no\">565</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"566\"><span class=\"c-no\">566</span><span class=\"c-src\">        total_agents = len(config.agents.profiles)</span></div>\n<div class=\"c-line\" data-line=\"567\"><span class=\"c-no\">567</span><span class=\"c-src\">        disabled_count = total_agents - len(agent_ids)</span></div>\n<div class=\"c-line\" data-line=\"568\"><span class=\"c-no\">568</span><span class=\"c-src\">        logger.debug(</span></div>\n<div class=\"c-line\" data-line=\"569\"><span class=\"c-no\">569</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;Starting {len(agent_ids)} enabled agent(s) &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"570\"><span class=\"c-no\">570</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;({disabled_count} disabled)&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"571\"><span class=\"c-no\">571</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"572\"><span class=\"c-no\">572</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"573\"><span class=\"c-no\">573</span><span class=\"c-src\">        <span class=\"c-kw\">async</span> <span class=\"c-kw\">def</span> start_single_agent(agent_id: str) -&gt; tuple[str, bool]:</span></div>\n<div class=\"c-line\" data-line=\"574\"><span class=\"c-no\">574</span><span class=\"c-src\">            <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;Start a single agent with error handling.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"575\"><span class=\"c-no\">575</span><span class=\"c-src\">            <span class=\"c-kw\">try</span>:</span></div>\n<div class=\"c-line\" data-line=\"576\"><span class=\"c-no\">576</span><span class=\"c-src\">                logger.debug(f<span class=\"c-str\">&quot;Starting agent: {agent_id}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"577\"><span class=\"c-no\">577</span><span class=\"c-src\">                <span class=\"c-kw\">await</span> <span class=\"c-kw\">self</span>.get_agent(agent_id)</span></div>\n<div class=\"c-line\" data-line=\"578\"><span class=\"c-no\">578</span><span class=\"c-src\">                logger.debug(f<span class=\"c-str\">&quot;Agent started successfully: {agent_id}&quot;</span>)</span></div>\n<div class=\"c-line\" data-line=\"579\"><span class=\"c-no\">579</span><span class=\"c-src\">                <span class=\"c-kw\">return</span> (agent_id, <span class=\"c-kw\">True</span>)</span></div>\n<div class=\"c-line\" data-line=\"580\"><span class=\"c-no\">580</span><span class=\"c-src\">            <span class=\"c-kw\">except</span> Exception <span class=\"c-kw\">as</span> e:</span></div>\n<div class=\"c-line\" data-line=\"581\"><span class=\"c-no\">581</span><span class=\"c-src\">                logger.error(</span></div>\n<div class=\"c-line\" data-line=\"582\"><span class=\"c-no\">582</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;Failed to start agent {agent_id}: {e}. &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"583\"><span class=\"c-no\">583</span><span class=\"c-src\">                    f<span class=\"c-str\">&quot;Continuing with other agents...&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"584\"><span class=\"c-no\">584</span><span class=\"c-src\">                )</span></div>\n<div class=\"c-line\" data-line=\"585\"><span class=\"c-no\">585</span><span class=\"c-src\">                <span class=\"c-kw\">return</span> (agent_id, <span class=\"c-kw\">False</span>)</span></div>\n<div class=\"c-line\" data-line=\"586\"><span class=\"c-no\">586</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"587\"><span class=\"c-no\">587</span><span class=\"c-src\">        <span class=\"c-com\"># Truly parallel: get_agent releases lock during workspace startup</span></span></div>\n<div class=\"c-line\" data-line=\"588\"><span class=\"c-no\">588</span><span class=\"c-src\">        results = <span class=\"c-kw\">await</span> asyncio.gather(</span></div>\n<div class=\"c-line\" data-line=\"589\"><span class=\"c-no\">589</span><span class=\"c-src\">            *[start_single_agent(agent_id) <span class=\"c-kw\">for</span> agent_id <span class=\"c-kw\">in</span> agent_ids],</span></div>\n<div class=\"c-line\" data-line=\"590\"><span class=\"c-no\">590</span><span class=\"c-src\">            return_exceptions=<span class=\"c-kw\">False</span>,</span></div>\n<div class=\"c-line\" data-line=\"591\"><span class=\"c-no\">591</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"592\"><span class=\"c-no\">592</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"593\"><span class=\"c-no\">593</span><span class=\"c-src\">        <span class=\"c-com\"># Build result mapping</span></span></div>\n<div class=\"c-line\" data-line=\"594\"><span class=\"c-no\">594</span><span class=\"c-src\">        result_map = dict(results)</span></div>\n<div class=\"c-line\" data-line=\"595\"><span class=\"c-no\">595</span><span class=\"c-src\">        success_count = sum(1 <span class=\"c-kw\">for</span> success <span class=\"c-kw\">in</span> result_map.values() <span class=\"c-kw\">if</span> success)</span></div>\n<div class=\"c-line\" data-line=\"596\"><span class=\"c-no\">596</span><span class=\"c-src\">        logger.info(</span></div>\n<div class=\"c-line\" data-line=\"597\"><span class=\"c-no\">597</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;Agent startup complete: {success_count}/{len(agent_ids)} &quot;</span></span></div>\n<div class=\"c-line\" data-line=\"598\"><span class=\"c-no\">598</span><span class=\"c-src\">            f<span class=\"c-str\">&quot;agents started successfully, {disabled_count} disabled&quot;</span>,</span></div>\n<div class=\"c-line\" data-line=\"599\"><span class=\"c-no\">599</span><span class=\"c-src\">        )</span></div>\n<div class=\"c-line\" data-line=\"600\"><span class=\"c-no\">600</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"601\"><span class=\"c-no\">601</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> result_map</span></div>\n<div class=\"c-line\" data-line=\"602\"><span class=\"c-no\">602</span><span class=\"c-src\">&nbsp;</span></div>\n<div class=\"c-line\" data-line=\"603\"><span class=\"c-no\">603</span><span class=\"c-src\">    <span class=\"c-kw\">def</span> __repr__(<span class=\"c-kw\">self</span>) -&gt; str:</span></div>\n<div class=\"c-line\" data-line=\"604\"><span class=\"c-no\">604</span><span class=\"c-src\">        <span class=\"c-str\">&quot;&quot;</span><span class=\"c-str\">&quot;String representation of manager.&quot;</span><span class=\"c-str\">&quot;&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"605\"><span class=\"c-no\">605</span><span class=\"c-src\">        loaded = list(<span class=\"c-kw\">self</span>.agents.keys())</span></div>\n<div class=\"c-line\" data-line=\"606\"><span class=\"c-no\">606</span><span class=\"c-src\">        <span class=\"c-kw\">return</span> f<span class=\"c-str\">&quot;MultiAgentManager(loaded_agents={loaded})&quot;</span></span></div>\n<div class=\"c-line\" data-line=\"607\"><span class=\"c-no\">607</span><span class=\"c-src\">&nbsp;</span></div>\n</div>", "lines": 607, "explanation": "QwenPaw MultiAgentManager 管多 Agent 生命周期：get_agent 延迟加载每个 Agent 工作空间，reload_agent 零停机热重载。配合 agentscope 服务层 TeamCreate/AgentCreate/TeamSay + MessageBus 实现 leader-worker 多 Agent。换 Redis MessageBus 即多 worker 横向扩展、多租户。", "knowledge_points": [{"title": "多 Agent 编排", "body": "服务层 Team 工具（TeamCreate/AgentCreate/TeamSay）+ MessageBus（InMemory/Redis）；Leader 动态调度 Worker；非 1.0 代码 pipeline；MultiAgentManager 管生命周期零停机重载。"}], "related_docs": ["W11-多Agent协作平台实战(上)"]};
